import { createContext, useContext } from 'react'
import type { ListExpenses } from '../../application/ListExpenses'
import type { SubmitExpense } from '../../application/SubmitExpense'

export type ExpenseUseCases = {
  listExpenses: ListExpenses
  submitExpense: SubmitExpense
}

export const ExpenseUseCasesContext = createContext<ExpenseUseCases | null>(null)

export const useExpenseUseCases = (): ExpenseUseCases => {
