import { useCallback, useEffect, useState } from 'react'
import type { ExpenseViewModel } from '../../application/ExpenseViewModel'
import type { FieldErrors, NewExpense } from '../../application/NewExpense'
import { useExpenseUseCases } from '../useExpenseUseCases/useExpenseUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpenseUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({})
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    let cancelled = false
    listExpenses
      .execute()
      .then((items) => {
        if (!cancelled) setExpenses(items)
      })
      .catch((error: unknown) => {
        if (!cancelled) setLoadError(error instanceof Error ? error.message : 'Could not load expenses')
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<boolean> => {
      setSubmitting(true)
      setSubmitError(null)
      try {
        const result = await submitExpense.execute(expense)
        if (result.ok) {
          setFieldErrors({})
          setExpenses((current) => [...current, result.expense])
          return true
        }
        setFieldErrors(result.errors)
        return false
      } catch (error) {
        setSubmitError(error instanceof Error ? error.message : 'Could not submit the expense')
        return false
      } finally {
        setSubmitting(false)
      }
    },
    [submitExpense],
  )

  return { expenses, loading, loadError, submit, submitting, fieldErrors, submitError }
}
